import * as T from './vendor/three.module.js';
const material=color=>new T.MeshStandardMaterial({color,roughness:.78,metalness:.01});
function sphere(g,m,p,s){const x=new T.Mesh(new T.SphereGeometry(1,48,32),m);x.position.set(...p);x.scale.set(...s);g.add(x);return x}
function tube(g,m,points,r=.01){const curve=new T.CatmullRomCurve3(points.map(p=>new T.Vector3(...p)));const mesh=new T.Mesh(new T.TubeGeometry(curve,32,r,6,false),m);g.add(mesh);return mesh}
const featherMaterials=new Map();
function featherMaterial(color){if(featherMaterials.has(color))return featherMaterials.get(color);const c=document.createElement('canvas');c.width=128;c.height=512;const ctx=c.getContext('2d');ctx.fillStyle=color;ctx.fillRect(0,0,128,512);const grad=ctx.createLinearGradient(0,0,128,0);grad.addColorStop(0,'rgba(0,0,0,.24)');grad.addColorStop(.46,'rgba(255,255,255,.10)');grad.addColorStop(.52,'rgba(0,0,0,.17)');grad.addColorStop(1,'rgba(255,255,255,.08)');ctx.fillStyle=grad;ctx.fillRect(0,0,128,512);ctx.strokeStyle='rgba(230,240,222,.15)';ctx.lineWidth=.65;for(let y=3;y<512;y+=4){ctx.beginPath();ctx.moveTo(64,y);ctx.lineTo(0,y+28);ctx.moveTo(64,y);ctx.lineTo(128,y+34);ctx.stroke()}ctx.strokeStyle='rgba(185,207,186,.38)';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(64,0);ctx.lineTo(64,512);ctx.stroke();const tex=new T.CanvasTexture(c);tex.colorSpace=T.SRGBColorSpace;tex.anisotropy=4;const m=new T.MeshStandardMaterial({map:tex,roughness:.67,side:T.DoubleSide,metalness:.025});featherMaterials.set(color,m);return m}
function feather(g,a,b,width,color,curve=.04){const start=new T.Vector3(...a),end=new T.Vector3(...b),length=start.distanceTo(end),verts=[],uv=[],indices=[];const segments=20;for(let j=0;j<=segments;j++){const t=j/segments,w=width*Math.pow(Math.sin(Math.PI*t),.60)*(1-.2*t);for(let k=0;k<3;k++){const side=k-1;verts.push(t*length,Math.sin(Math.PI*t)*curve+(k===1?.018:0),side*w);uv.push(k/2,t)}}for(let j=0;j<segments;j++)for(let k=0;k<2;k++){const n=j*3+k;indices.push(n,n+3,n+1,n+1,n+3,n+4)}const geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute(verts,3));geo.setAttribute('uv',new T.Float32BufferAttribute(uv,2));geo.setIndex(indices);geo.computeVertexNormals();const f=new T.Mesh(geo,featherMaterial(color));f.position.copy(start);f.quaternion.setFromUnitVectors(new T.Vector3(1,0,0),end.sub(start).normalize());g.add(f);return f}
function wing(macaw=false){const g=new T.Group();const dark=macaw?'#1c6684':'#27363b',secondary=macaw?'#c99c36':'#384949',cover=macaw?'#c34632':'#202e2c';for(let i=0;i<12;i++){const t=i/11;feather(g,[-.08-i*.047,.0,.45+t*.25],[-1.17-t*.12,.045,1.14+t*1.20],.12+(1-t)*.025,dark,.07)}for(let i=0;i<10;i++){const t=i/9;feather(g,[.12-t*.36,.045,.25+t*.68],[-.88-t*.04,.08,.43+t*.72],.12,secondary,.06)}for(let row=0;row<3;row++)for(let i=0;i<13;i++){const t=i/12;feather(g,[.26-t*.47,.10+row*.014,.09+t*(.85-row*.1)],[-.28-t*.30,.13+row*.013,.19+t*(.94-row*.1)],.057,cover,.033)}sphere(g,material(cover),[.01,.08,.18],[.32,.13,.47]);return g}
function bill(g,macaw){const steps=36,sides=36,vertices=[],colors=[],indices=[],uv=[];const palette=macaw?['#e7cda4','#dcb682','#34342d']:['#94bf5f','#ead451','#dc733f','#a73f2b'];for(let j=0;j<=steps;j++){const t=j/steps;const x=1.04+t*(macaw?.58:1.15),height=macaw?.27*Math.pow(1-t,.65):.28*Math.pow(1-t,.7),zwidth=macaw?.16*Math.pow(1-t,.8):.195*Math.pow(1-t,.6);const cy=macaw?.39-.48*t*t:.37-.08*t*t;for(let k=0;k<=sides;k++){const ang=k/sides*Math.PI*2;vertices.push(x,cy+Math.cos(ang)*height,Math.sin(ang)*zwidth);let color;if(macaw)color=new T.Color(t>.63?palette[2]:palette[Math.cos(ang)<-.1?1:0]);else color=new T.Color(t>.80?palette[3]:Math.cos(ang)>.25?palette[0]:Math.cos(ang)<-.55?palette[2]:palette[1]);colors.push(color.r,color.g,color.b);uv.push(t,k/sides)}}for(let j=0;j<steps;j++)for(let k=0;k<sides;k++){const a=j*(sides+1)+k;indices.push(a,a+1,a+sides+1,a+1,a+sides+2,a+sides+1)}const geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute(vertices,3));geo.setAttribute('color',new T.Float32BufferAttribute(colors,3));geo.setAttribute('uv',new T.Float32BufferAttribute(uv,2));geo.setIndex(indices);geo.computeVertexNormals();g.add(new T.Mesh(geo,new T.MeshStandardMaterial({vertexColors:true,roughness:.36,side:T.DoubleSide})));if(!macaw){for(const side of [-1,1])tube(g,material('#594e2b'),[[1.04,.22,side*.185],[1.4,.21,side*.167],[1.8,.205,side*.11],[2.13,.235,side*.046]],.008);for(const side of [-1,1])sphere(g,material('#445836'),[1.14,.43,side*.19],[.016,.013,.008])}}
export function bird(macaw=false){const g=new T.Group(),body=new T.Group();g.add(body);const plumage=material(macaw?'#c93e2b':'#1a2625'),throat=material(macaw?'#d84c34':'#e4c656');sphere(body,plumage,[-.12,0,0],[.91,.39,.34]);sphere(body,throat,[.53,-.075,0],[.44,.38,.30]);sphere(body,plumage,[.82,.30,0],[.35,.34,.28]);if(!macaw){sphere(body,material('#c44126'),[-.68,-.21,0],[.26,.15,.23])}else{for(const s of [-1,1])sphere(body,material('#ecdcb8'),[.97,.32,s*.224],[.21,.22,.044])}for(const s of [-1,1]){sphere(body,material(macaw?'#d7c99e':'#559780'),[.90,.41,s*.257],[.079,.082,.020]);sphere(body,material('#0e1814'),[.917,.415,s*.279],[.045,.047,.015]);sphere(body,material('#eef5e5'),[.931,.434,s*.290],[.011,.012,.006]);if(macaw)for(let i=0;i<4;i++)tube(body,material('#824b3b'),[[1.03,.38-i*.045,s*.264],[.98,.375-i*.045,s*.273],[.92,.37-i*.045,s*.272]],.0025)}bill(body,macaw);const wings=[];for(const side of [-1,1]){const w=wing(macaw);w.position.set(.06,.08,side*.17);w.scale.z=side;body.add(w);wings.push(w)}for(let i=0;i<7;i++){const s=(i-3)/3;feather(body,[-.68,-.075,s*.07],[macaw?-2.57:-1.78,-.23,s*(macaw?.28:.43)],macaw?.077:.13,macaw?(Math.abs(s)>.6?'#2d7394':'#b83229'):'#2c3836',.025)}for(let row=0;row<7;row++){const x=.25-row*.13;for(let i=0;i<22;i++){const phi=i/22*Math.PI*2,r=Math.sqrt(1-Math.pow((x+.12)/.93,2)),rb=Math.sqrt(Math.max(.01,1-Math.pow((x-.08+.12)/.93,2)));const f=feather(body,[x,r*.405*Math.cos(phi),r*.355*Math.sin(phi)],[x-.19,rb*.415*Math.cos(phi),rb*.365*Math.sin(phi)],.045,macaw?'#b9452d':'#263630',.005);f.rotateX(-phi)}}const feet=material('#697a7d');for(const s of [-1,1]){tube(body,feet,[[-.36,-.29,s*.2],[-.54,-.47,s*.23],[-.63,-.41,s*.24]],.018);for(let i=0;i<3;i++)tube(body,feet,[[-.62,-.40,s*.23],[-.70,-.37,s*.25+(i-1)*.035],[-.76,-.34,s*.25+(i-1)*.038]],.008)}g.userData.body=body;g.userData.wings=wings;g.userData.head=new T.Vector3(1.1,.30,0);g.userData.isBird=true;return g}
